// A tiny corpus with one invented, unguessable fact. If the final answer
// contains it, retrieval demonstrably worked — a model cannot know this
// from training data.
const passages = [
  {
    source: 'handbook.md',
    text:
      'Escalation policy. Any incident that stays unresolved for more than ' +
      'forty minutes is escalated to the Kestrel rota. The Kestrel rota is ' +
      'staffed on weekday evenings only; outside those hours incidents go ' +
      'to the on-call duty engineer instead.',
  },
  {
    source: 'handbook.md',
    text:
      'Backups. Nightly snapshots run at 02:15 in the cluster timezone and ' +
      'are retained for fourteen days. Restores are rehearsed once a ' +
      'quarter against a scratch namespace.',
  },
  {
    source: 'onboarding.md',
    text:
      'New starters get read-only access on day one. Write access to ' +
      'production is granted after the second week, and only once the ' +
      'escalation drill has been completed with a buddy.',
  },
];

return passages.map((p, index) => ({
  json: { collection: 'ods_rag_demo', source: p.source, index, text: p.text },
}));

// Deterministic ids so re-running the demo updates the same three points
// rather than growing the collection. Same scheme as the RAG Pipeline
// Trigger template.
const crypto = require('crypto');
const NAMESPACE_URL = '6ba7b811-9dad-11d1-80b4-00c04fd430c8';

function uuidv5(name) {
  const nsBytes = Buffer.from(NAMESPACE_URL.replace(/-/g, ''), 'hex');
  const hash = crypto
    .createHash('sha1')
    .update(Buffer.concat([nsBytes, Buffer.from(name, 'utf8')]))
    .digest();
  const bytes = Buffer.from(hash.subarray(0, 16));
  bytes[6] = (bytes[6] & 0x0f) | 0x50;
  bytes[8] = (bytes[8] & 0x3f) | 0x80;
  const hex = bytes.toString('hex');
  return [
    hex.slice(0, 8),
    hex.slice(8, 12),
    hex.slice(12, 16),
    hex.slice(16, 20),
    hex.slice(20),
  ].join('-');
}

const embeddings = $input.all();
const passages = $('Seed Passages').all();

if (embeddings.length !== passages.length) {
  throw new Error(
    `Embedding count ${embeddings.length} does not match passage count ${passages.length}`
  );
}

const points = embeddings.map((item, i) => {
  const vector = item.json?.data?.[0]?.embedding;
  if (!Array.isArray(vector)) {
    throw new Error(`Embedding ${i} has no vector — check the embeddings service`);
  }
  const p = passages[i].json;
  return {
    id: uuidv5(`demo:${p.source}#${p.index}`),
    vector,
    payload: { text: p.text, source: p.source, chunk_index: p.index },
  };
});

return [{ json: { points } }];

// Accept both Qdrant shapes: /points/query returns { result: { points } },
// the older /points/search returned { result: [...] }.
const payload = $input.first().json || {};
const raw = payload.result?.points ?? payload.result ?? [];
const hits = Array.isArray(raw) ? raw : [];

const kept = hits.map((h, i) => ({
  rank: i + 1,
  score: typeof h?.score === 'number' ? Number(h.score.toFixed(4)) : null,
  source: h?.payload?.source ?? 'unknown',
  text: String(h?.payload?.text ?? ''),
}));

return [{
  json: {
    question: $('Ask The Question').first().json.question,
    retrieved: kept.length,
    sources: kept.map(({ rank, score, source }) => ({ rank, score, source })),
    context: kept.map((h) => `[${h.rank}] (${h.source}) ${h.text}`).join('\n\n'),
  },
}];

